/* Recording is automatically transcribed after stopping while the panel is open; saved keys are never returned to the browser. */
const RecallAssistant={
 data:()=>({configProvider:"siliconflow",configAsrModel:"FunAudioLLM/SenseVoiceSmall",configOpen:false,configKey:"",configRegion:"beijing",configTextModel:"qwen-plus",configMessage:"",configTests:{},assistantOpen:false,assistantStatus:null,assistantText:'',assistantBusy:false,assistantError:'',assistantPending:null,assistantAnswer:null,assistantUndo:null,assistantRecording:false,assistantAudio:null,assistantSeconds:0,assistantTimer:null,assistantRecorder:null,assistantStream:null,assistantNotice:null,micPoints:"0,18 120,18",micStatus:"等待声音",micContext:null,micFrame:null,assistantHistory:[],voiceReply:false,voiceSubmit:true}),
 methods:{
  speakAnswer(text){if(!this.voiceReply||!window.speechSynthesis)return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='zh-CN';window.speechSynthesis.speak(utterance)},
  stopSpeaking(){window.speechSynthesis?.cancel()},
  async sendAssistant(){if(this.assistantBusy||!this.assistantText.trim())return;this.stopSpeaking();await this.parseAssistant();if(this.assistantPending&&!this.assistantPending.clarification){await this.applyAssistant();if(this.assistantAnswer){this.assistantHistory.push({question:this.assistantText,answer:this.assistantAnswer.answer});this.assistantHistory=this.assistantHistory.slice(-6);this.speakAnswer(this.assistantAnswer.answer)}}},

  stopMicMeter(){cancelAnimationFrame(this.micFrame);this.micFrame=null;if(this.micContext){this.micContext.close().catch(()=>{});this.micContext=null}this.micPoints='0,18 120,18';this.micStatus='等待声音'},
  async startMicMeter(stream){this.stopMicMeter();try{const ctx=new AudioContext();this.micContext=Vue.markRaw(ctx);const analyser=ctx.createAnalyser();analyser.fftSize=256;ctx.createMediaStreamSource(stream).connect(analyser);await ctx.resume();const samples=new Uint8Array(256);let last=0;const tick=t=>{if(!this.assistantRecording)return;if(t-last>65){last=t;analyser.getByteTimeDomainData(samples);const rms=Math.sqrt(samples.reduce((sum,v)=>sum+((v-128)/128)**2,0)/samples.length);this.micStatus=rms>.012?'收到声音':'等待声音';if(rms>.012){this.heardVoice=true;this.lastVoiceAt=Date.now()}else if((this.autoStop||this.continuous)&&this.heardVoice&&Date.now()-this.lastVoiceAt>2200&&this.assistantSeconds>2){this.stopRecording();return}if(this.assistantSeconds>=10&&!this.heardVoice){this.recordCancelled=true;this.continuous=false;this.assistantError='没有检测到声音，请检查麦克风后重试。';this.assistantStage='未检测到声音';this.assistantRetryKind='recording';this.stopRecording();return}this.micPoints=Array.from({length:60},(_,i)=>{const v=(samples[i*4]-128)/128;return (i*120/59).toFixed(1)+','+(18-Math.max(-1,Math.min(1,v*3))*16).toFixed(1)}).join(' ')}this.micFrame=requestAnimationFrame(tick)};this.micFrame=requestAnimationFrame(tick)}catch(e){this.stopMicMeter();this.micStatus='音量检测不可用';this.heardVoice=true}},

  async openSettings(){if(!this.configOpen){await this.openConfig()}else{await this.openAssistant()}},
  async openConfig(){this.configOpen=!this.configOpen;this.configMessage='';this.configTests={};if(this.configOpen){await this.openAssistant();this.configRegion=this.assistantStatus?.region==='singapore'?'singapore':'beijing';this.configProvider=this.assistantStatus?.configured?(this.assistantStatus?.provider_id||'bailian'):'siliconflow';this.configTextModel=this.assistantStatus?.configured?this.assistantStatus.text_model:'';this.configAsrModel=this.assistantStatus?.configured?this.assistantStatus.asr_model:'FunAudioLLM/SenseVoiceSmall'}},
  changeProvider(){this.configKey='';this.configTests={};this.configMessage='';this.configTextModel=this.configProvider==='bailian'?'qwen-plus':'';this.configAsrModel=this.configProvider==='bailian'?'qwen3-asr-flash':'FunAudioLLM/SenseVoiceSmall'},
  configPayload(){return {provider:this.configProvider,key:this.configKey,region:this.configRegion,text_model:this.configTextModel,asr_model:this.configAsrModel}},
  async saveConfig(){this.assistantBusy=true;this.assistantError='';this.configMessage='';try{const v=await this.assistantApi('config',this.configPayload());this.configKey='';this.assistantStatus=v;this.configMessage=v.message}catch(e){this.assistantError=e.message}finally{this.assistantBusy=false}},
  async testConfig(kind){this.assistantBusy=true;this.assistantError='';this.configTests[kind]='测试中…';try{const v=await this.assistantApi('config/test',{...this.configPayload(),kind});this.configTests[kind]=v.message+' 耗时'+(v.elapsed_ms/1000).toFixed(1)+'秒。'}catch(e){this.configTests[kind]='测试失败：'+e.message}finally{this.assistantBusy=false}},

  currentFilters(){return Object.fromEntries(['domain','year','query','category','risk','scope','from','to','month'].map(k=>[k,this[k]]))},
  async parseAssistant(){this.assistantBusy=true;this.assistantError='';this.assistantPending=null;this.assistantAnswer=null;this.assistantNotice=null;try{this.assistantPending=await this.assistantApi('intent',{text:this.assistantText,filters:this.currentFilters(),history:this.assistantHistory})}catch(e){this.assistantError=e.message}finally{this.assistantBusy=false}},
  async applyAssistant(){if(!this.assistantPending||this.assistantPending.clarification)return;const f=this.assistantPending.filters;if(f.from&&f.to&&f.from>f.to){this.assistantError='起始日期晚于结束日期';return}this.assistantUndo={filters:this.currentFilters(),page:this.page};Object.assign(this,f);this.page=1;this.assistantPending=null;await this.analyzeAssistant()},
  undoAssistant(){if(this.assistantUndo){Object.assign(this,this.assistantUndo.filters);this.page=this.assistantUndo.page;this.assistantUndo=null;this.assistantAnswer=null;this.assistantPending=null}},
  async explainNotice(){const n=this.detail;this.detail=null;await this.openAssistant();await this.analyzeAssistant(n)},
  stopRecording(){this.stopMicMeter();if(this.assistantRecorder?.state==='recording')this.assistantRecorder.stop()},
  async audioToWav(blob){const ctx=new AudioContext();try{const source=await ctx.decodeAudioData(await blob.arrayBuffer());if(source.duration>61)throw Error('录音超过60秒');const offline=new OfflineAudioContext(1,Math.ceil(source.duration*16000),16000);const node=offline.createBufferSource();node.buffer=source;node.connect(offline.destination);node.start();const samples=(await offline.startRendering()).getChannelData(0);const buffer=new ArrayBuffer(44+samples.length*2),v=new DataView(buffer);const word=(p,s)=>{for(let i=0;i<s.length;i++)v.setUint8(p+i,s.charCodeAt(i))};word(0,'RIFF');v.setUint32(4,36+samples.length*2,true);word(8,'WAVE');word(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,16000,true);v.setUint32(28,32000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);word(36,'data');v.setUint32(40,samples.length*2,true);samples.forEach((x,i)=>v.setInt16(44+i*2,Math.max(-1,Math.min(1,x))*(x<0?32768:32767),true));return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(new Blob([buffer],{type:'audio/wav'}))})}finally{await ctx.close()}},
  closeAssistant(){this.stopSpeaking();this.configKey="";if(this.assistantRecording)this.stopRecording();this.assistantOpen=false}
 },
 beforeUnmount(){this.stopSpeaking();this.stopMicMeter();clearInterval(this.assistantTimer);this.assistantStream?.getTracks().forEach(t=>t.stop())}
};
